import { Box, Typography, Button, Grid, Stack, CircularProgress } from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutline';
import BoltIcon from '@mui/icons-material/Bolt';
import { useDispatch, useSelector } from 'react-redux';
import { useEffect, useState } from 'react';
import { toast } from 'react-hot-toast';
import { setSelectedPlan } from '../../../Redux/Slices/AuthSlice';
import { createCheckoutSession } from '../../../utils/stripeApi';
import DisplayChip from '../../../components/DisplayChip';
import { PLANS } from '../../../constants/signupPlans';

const Plans = () => {
  const dispatch = useDispatch();
  const signupData = useSelector((state) => state.auth.signupData);

  const [loadingPlan, setLoadingPlan] = useState(null);

  // Lock the user into the plans/checkout step: once signup is done they should
  // not be able to navigate back (to signup) using the browser back button.
  useEffect(() => {
    window.history.pushState(null, '', window.location.href);

    const handlePopState = () => {
      window.history.pushState(null, '', window.location.href);
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const handleSelect = async (plan) => {
    if (loadingPlan) return;

    const billingLabel = plan.id === 'annual' ? 'Yearly' : 'Monthly';
    try {
      sessionStorage.setItem('selectedPlanLabel', billingLabel);
    } catch (e) {
      // sessionStorage may be unavailable; non-fatal.
    }

    dispatch(
      setSelectedPlan({
        id: plan.id,
        name: plan.name,
        price: plan.price,
        period: plan.period,
        planId: plan.planId,
        lookupKey: plan.lookupKey,
        priceId: plan.priceId || null,
      }),
    );

    setLoadingPlan(plan.id);

    try {
      const origin = window.location.origin;
      const data = await createCheckoutSession({
        mode: 'subscription',
        quantity: 1,
        
        successUrl: `${origin}/app-payment-success?session_id={CHECKOUT_SESSION_ID}`,
        cancelUrl: `${origin}/app-payment-cancel`,
        lookupKey: plan.lookupKey,
        priceId: plan.priceId,
        planId: plan.planId,
        customerEmail: signupData?.email,
      });

      if (data?.checkout_url) {
        window.location.href = data.checkout_url;
      } else {
        throw new Error('Checkout URL not received');
      }
    } catch (error) {
      toast.error(error.message || 'Unable to start checkout');
      setLoadingPlan(null);
    }
  };

  return (
    <Box sx={{ width: '100%', maxWidth: 1000, mx: 'auto' }}>
      <Box sx={{ textAlign: 'center', mb: { xs: 4, sm: 6 } }}>
        <DisplayChip
          icon={<BoltIcon sx={{ fontSize: 16 }} />}
          label="7 DAYS FREE TRIAL ON BOTH PLANS"
          sx={{
            bgcolor: 'rgba(255, 196, 0, 0.12)',
            color: '#FFC400',
            fontWeight: 800,
            letterSpacing: '0.08em',
            border: '1px solid rgba(255, 196, 0, 0.45)',
            mb: 2,
            '& .MuiChip-icon': { color: '#FFC400' },
          }}
        />
        <Typography
          variant="h3"
          sx={{
            color: 'white',
            fontWeight: 800,
            fontSize: { xs: '1.75rem', sm: '2.25rem', md: '2.75rem' },
          }}
        >
          Choose Your Plan
        </Typography>
        <Typography
          variant="body1"
          sx={{ color: 'text.secondary', mt: 1.5, maxWidth: 560, mx: 'auto' }}
        >
          Pick the plan that fits you best. Cancel anytime, no hidden fees.
        </Typography>
      </Box>

      <Grid container spacing={{ xs: 3, md: 4 }} justifyContent="center">
        {PLANS.map((plan) => (
          <Grid item xs={12} sm={6} key={plan.id}>
            <Box
              sx={{
                position: 'relative',
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                p: { xs: 3, sm: 4 },
                borderRadius: '24px',
                backgroundColor: 'rgba(0, 0, 0, 0.7)',
                backdropFilter: 'blur(16px)',
                border: plan.featured
                  ? '1.5px solid #4CC66E'
                  : '1px solid rgba(255, 255, 255, 0.1)',
                boxShadow: plan.featured
                  ? '0 12px 40px rgba(76, 198, 110, 0.18)'
                  : '0 8px 32px rgba(0, 0, 0, 0.6)',
                transition: 'all 0.4s cubic-bezier(0.23, 1, 0.32, 1)',
                '&:hover': {
                  transform: 'translateY(-8px)',
                  borderColor: '#4CC66E',
                },
              }}
            >
              {plan.featured && (
                <DisplayChip
                  label={plan.badge}
                  size="small"
                  sx={{
                    position: 'absolute',
                    top: 20,
                    right: 24,
                    bgcolor: 'primary.main',
                    color: '#000',
                    fontWeight: 800,
                    fontSize: '0.65rem',
                    letterSpacing: '0.06em',
                  }}
                />
              )}

              <Typography
                sx={{
                  color: 'primary.main',
                  fontWeight: 800,
                  fontSize: '1.1rem',
                  mb: 1.5,
                }}
              >
                {plan.name}
              </Typography>

              <Stack direction="row" alignItems="baseline" spacing={1} sx={{ mb: 1.5 }}>
                <Typography
                  sx={{
                    color: 'white',
                    fontWeight: 900,
                    fontSize: { xs: '2.5rem', sm: '3rem' },
                    lineHeight: 1,
                    letterSpacing: '-0.03em',
                  }}
                >
                  {plan.price}
                </Typography>
                <Typography
                  sx={{ color: 'text.secondary', fontWeight: 600, fontSize: '1rem' }}
                >
                  {plan.period}
                </Typography>
              </Stack>

              <Typography
                variant="body2"
                sx={{ color: 'text.secondary', mb: 3, minHeight: 42 }}
              >
                {plan.description}
              </Typography>

              <Stack spacing={1.5} sx={{ mb: 4, flexGrow: 1 }}>
                {plan.features.map((feature) => (
                  <Stack
                    key={feature}
                    direction="row"
                    alignItems="center"
                    spacing={1.25}
                  >
                    <CheckCircleOutlineIcon
                      sx={{ color: 'primary.main', fontSize: 20 }}
                    />
                    <Typography variant="body2" sx={{ color: 'white' }}>
                      {feature}
                    </Typography>
                  </Stack>
                ))}
              </Stack>

              <Button
                fullWidth
                variant={plan.featured ? 'contained' : 'outlined'}
                size="large"
                onClick={() => handleSelect(plan)}
                disabled={Boolean(loadingPlan)}
                startIcon={
                  loadingPlan === plan.id ? (
                    <CircularProgress size={18} color="inherit" />
                  ) : null
                }
                sx={{ fontWeight: 700, py: 1.25 }}
              >
                {loadingPlan === plan.id ? 'Redirecting…' : plan.cta}
              </Button>
            </Box>
          </Grid>
        ))}
      </Grid>

     
    </Box>
  );
};

export default Plans;
